FIT_UINT16 Mesg::GetActiveSubFieldIndex(const FIT_UINT8 fieldNum) const
{
    // cache Profile::GetField results
    static const Profile::FIELD* cachePtr[256];
    static FIT_UINT16 cacheMesg[256];
    static FIT_UINT8 cacheField[256];
    static bool cacheValid[256];

    const FIT_MESG_NUM mesgNum = GetNum();
    const unsigned idx = ((unsigned)mesgNum * 31u + fieldNum) & 255u;

    const Profile::FIELD* field;
    if (cacheValid[idx] && cacheMesg[idx] == mesgNum && cacheField[idx] == fieldNum)
    {
        field = cachePtr[idx];
    }
    else
    {
        field = Profile::GetField(mesgNum, fieldNum);
        cacheValid[idx] = true;
        cacheMesg[idx] = mesgNum;
        cacheField[idx] = fieldNum;
        cachePtr[idx] = field;
    }

    if (field == FIT_NULL)
        return FIT_SUBFIELD_INDEX_MAIN_FIELD;

    for (int i = 0; i < (int) field->numSubFields; i++)
    {
        const Profile::SUBFIELD& subField = field->subFields[i];
        for (int j = 0; j < (int) subField.numMaps; j++)
        {
            const Field* refField = GetField(subField.maps[j].refFieldNum);
            if (refField != FIT_NULL)
            {
                FIT_FLOAT64 refValue = refField->GetFLOAT64Value(0, FIT_SUBFIELD_INDEX_MAIN_FIELD);
                refValue += ((refValue >= 0.0) ? (0.5) : (-0.5));
                if ((FIT_SINT32)refValue == subField.maps[j].refFieldValue)
                    return ((FIT_UINT16) i);
            }
        }
    }
    return FIT_SUBFIELD_INDEX_MAIN_FIELD;
}

